        ("-N, --no-pass", "Do not ask for a password (anonymous).", "Null sessions."),
        ("-U, --user=USER[%PASS]", "User name and optional password.", "Logging in."),
        ("-W, --workgroup=NAME", "Domain or workgroup.", "Domain accounts."),
        ("-I, --ip-address=IP", "Connect to this IP rather than resolving the name.", "Name problems."),
